 CoolingSnapshot Snapshot(){string startup="Indisponible";try{Reply reply=PipeClient.Send("status");if(!reply.Ok)throw new IOException(reply.Error);string prior=reply.Snapshot.Startup;bool auto=CoolingNative.Automatic();startup=prior=="ON"&&auto?"ON":prior=="OFF"&&!auto?"OFF":prior=="Desactive dans Windows"?prior:"Partiel";}catch{}lock(gate){state.Faulted=faulted;state.CanZero=state.CanControl&&!faulted&&!paused;state.Startup=startup;var j=new JavaScriptSerializer();return j.Deserialize<CoolingSnapshot>(j.Serialize(state));}}
