internal sealed class CoolingService:ServiceBase {
 CoolingEngine engine;public CoolingService(){ServiceName=CoolingPaths.Service;CanStop=true;CanShutdown=true;CanHandlePowerEvent=true;}
 protected override void OnStart(string[] args){engine=new CoolingEngine();engine.Start();}
 protected override void OnStop(){RequestAdditionalTime(15000);if(engine!=null){engine.Dispose();engine=null;}}
 protected override void OnShutdown(){if(engine!=null){engine.Dispose();engine=null;}}
 protected override bool OnPowerEvent(PowerBroadcastStatus status){if(engine!=null){if(status==PowerBroadcastStatus.Suspend)engine.Suspend();else if(status==PowerBroadcastStatus.ResumeAutomatic||status==PowerBroadcastStatus.ResumeSuspend)engine.Resume();}return true;}
}
